#include <vector>
#include <omp.h>

/* Return the product of the vector x with every odd indexed element inverted.
   i.e. x_0 * 1/x_1 * x_2 * 1/x_3 * x_4 ...
   The computation is performed in parallel using OpenMP and is correct for any
   number of threads.
*/
double productWithInverses(const std::vector<double>& x) {
    // Empty vector → neutral element of multiplication
    if (x.empty()) return 1.0;

    double prod = 1.0;                     // neutral element for multiplication
    const std::size_t n = x.size();

    // Parallel loop with a multiplication reduction.
    // Each iteration contributes a factor that is either x[i] (even i)
    // or 1.0/x[i] (odd i).
    #pragma omp parallel for reduction(*:prod) schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        double factor = (i % 2 == 0) ? x[i] : 1.0 / x[i];
        prod *= factor;
    }

    return prod;
}
