#include <vector>
#include <omp.h>

/* Return the product of the vector x with every odd indexed element inverted:
   x_0 * (1/x_1) * x_2 * (1/x_3) * ….
   The computation is parallelised with OpenMP but the final multiplication is
   performed sequentially to guarantee identical results for any thread count.
*/
double productWithInverses(const std::vector<double>& x) {
    // Empty vector → neutral element of multiplication
    if (x.empty()) return 1.0;

    const std::size_t n = x.size();
    std::vector<double> factor(n);

    // Compute each factor in parallel – no race conditions.
    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        factor[i] = (i % 2 == 0) ? x[i] : 1.0 / x[i];
    }

    // Combine the factors sequentially to obtain a deterministic result.
    double prod = 1.0;
    for (std::size_t i = 0; i < n; ++i) {
        prod *= factor[i];
    }

    return prod;
}
