#include <vector>
#include <omp.h>

/* Return the product of the vector x with every odd indexed element inverted:
   x_0 * (1/x_1) * x_2 * (1/x_3) * ….
   The computation is parallelised with OpenMP and yields the same result for
   any number of threads (order‑independent, no data races).
*/
double productWithInverses(const std::vector<double>& x) {
    if (x.empty()) return 1.0;                 // neutral element

    const std::size_t n = x.size();

    // Determine how many threads will actually be used.
    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        max_threads = omp_get_num_threads();
    }

    // One partial product per thread.
    std::vector<double> partial(max_threads, 1.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        double local_prod = 1.0;

        // Distribute the iterations statically; each thread works on its own
        // contiguous chunk, guaranteeing no overlap and thus no race.
        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < n; ++i) {
            double factor = (i % 2 == 0) ? x[i] : 1.0 / x[i];
            local_prod *= factor;
        }

        // Store the thread‑local result in a unique slot.
        partial[tid] = local_prod;
    }

    // Combine the per‑thread results sequentially – deterministic order.
    double result = 1.0;
    for (int i = 0; i < max_threads; ++i) {
        result *= partial[i];
    }
    return result;
}
